#pragma once

#include "../types/SourceTime.hpp"
#include "../types/SourceTimeNs.hpp"
#include "../types/SeriesIndex.hpp"
#include "../types/SeriesSeqNum.hpp"
#include "../types/RfqSide.hpp"
#include "../types/Type.hpp"
#include "../types/Capacity.hpp"
#include "../types/TotalQuantity.hpp"
#include "../types/WorkingPrice.hpp"
#include "../types/Participant.hpp"
#include "../types/AuctionId.hpp"
#include "../types/RfqStatus.hpp"
#include "../structs/MessageHeader.hpp"

namespace nyse::arcaoptions::deepfeed::pillar::v1_2_m {

#pragma pack(push, 1)

// Published for outright series. Generated by the matching engine to solicit interest in an auction or order.
struct OptionsSeriesRfqMessage {

    SourceTime source_time;
    SourceTimeNs source_time_ns;
    SeriesIndex series_index;
    SeriesSeqNum series_seq_num;
    RfqSide rfq_side;
    Type type;
    Capacity capacity;
    TotalQuantity total_quantity;
    WorkingPrice working_price;
    Participant participant;
    AuctionId auction_id;
    RfqStatus rfq_status;

    // the type code that selects this message in the dispatch switch
    static constexpr std::uint16_t message_type = 307;

    // parse method
    static OptionsSeriesRfqMessage* parse(std::byte* buffer) {
        return reinterpret_cast<OptionsSeriesRfqMessage*>(buffer);
    }

    // parse method const
    static const OptionsSeriesRfqMessage* parse(const std::byte* buffer) {
        return reinterpret_cast<const OptionsSeriesRfqMessage*>(buffer);
    }

    // parse the overlaid body from its selecting header
    static const OptionsSeriesRfqMessage* parse(const MessageHeader* header) {
        return reinterpret_cast<const OptionsSeriesRfqMessage*>(reinterpret_cast<const std::byte*>(header) + sizeof(MessageHeader));
    }
};

#pragma pack(pop)
}
